    println("pointer chase, 4 MB array (an L2 or L3 cache):     %8.1f ns per load".format(chase(4 shl 20, 20_000_000)))
    println("pointer chase, 256 MB array (main memory):         %8.1f ns per load".format(chase(256 shl 20, 10_000_000)))
