// an LRU map in a few lines: access order plus a size check after every put
public class LruMap<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;

    public LruMap(int capacity) {
        super(16, 0.75f, true);              // true: iterate from least to most recently used
        this.capacity = capacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;            // called after each put: drop the LRU entry if over
    }
}

LruMap<String, MerchantProfile> profiles = new LruMap<>(10_000);

